async def act(page):
    """
    Navigate to the Shipping report page, set the From/To dates to 08/05/2022 -> 03/01/2023,
    generate the report, and attempt an export (CSV) as the last action.

    Notes:
    - Do not change the "Your Language:" combobox (keep English).
    - KB helpers are dashboard-focused and not used because they do not support
      the Sales > Shipping report flow.
    """
    # Navigate to the Shipping report relative URL (idempotent)
    await page.goto('/index.php/admin/report/sales_shipping/shipping/')
    await page.wait_for_load_state('domcontentloaded')
    # small pause for UI scripts to run
    await page.wait_for_timeout(600)

    from_date = "08/05/2022"
    to_date = "03/01/2023"

    # Fill the From field (try several label variations)
    from_filled = False
    from_label_candidates = ["From", "From:", "from", "Start Date", "Start"]
    for label in from_label_candidates:
        try:
            locator = page.get_by_label(label)
            if await locator.count() > 0:
                await locator.fill(from_date)
                from_filled = True
                break
        except Exception:
            # ignore transient issues and try the next label
            continue

    # Fill the To field (try several label variations)
    to_filled = False
    to_label_candidates = ["To", "To:", "to", "End Date", "End"]
    for label in to_label_candidates:
        try:
            locator = page.get_by_label(label)
            if await locator.count() > 0:
                await locator.fill(to_date)
                to_filled = True
                break
        except Exception:
            continue

    # Allow any datepicker UI to settle
    await page.wait_for_timeout(400)

    # Try to click a generate/report button inside the form that contains the 'From' input (preferred)
    clicked_generate = False
    button_names = ["Show Report", "Show", "Refresh", "Filter", "Submit", "Apply", "Go"]

    try:
        forms = page.get_by_role("form")
        if await forms.count() > 0:
            # Prefer a form that contains the 'From' label
            form_with_from = forms.filter(has=page.get_by_label("From"))
            if await form_with_from.count() == 0:
                # try lowercase label fallback
                form_with_from = forms.filter(has=page.get_by_label("from"))

            if await form_with_from.count() > 0:
                for name in button_names:
                    btn = form_with_from.get_by_role("button", name=name)
                    if await btn.count() > 0:
                        await btn.click()
                        clicked_generate = True
                        break
    except Exception:
        clicked_generate = False

    # Global fallback: try to click a button with a likely name anywhere on the page
    if not clicked_generate:
        for name in button_names:
            try:
                btn = page.get_by_role("button", name=name)
                if await btn.count() > 0:
                    await btn.click()
                    clicked_generate = True
                    break
            except Exception:
                continue

    # If still not clicked, scan buttons for accessible names containing report/filter/show and click the first match
    if not clicked_generate:
        try:
            buttons = page.get_by_role("button")
            if await buttons.count() > 0:
                total = await buttons.count()
                for i in range(total):
                    b = buttons.nth(i)
                    try:
                        name = (await b.get_attribute('innerText')) or ""
                    except Exception:
                        name = ""
                    if name and ("report" in name.lower() or "filter" in name.lower() or "show" in name.lower()):
                        await b.click()
                        clicked_generate = True
                        break
        except Exception:
            pass

    # Wait for the report to generate / UI to update
    await page.wait_for_timeout(1200)

    # Attempt export as the last action (may navigate or trigger a download)
    export_candidates = ["Export to CSV", "Export CSV", "Export", "CSV", "Download CSV"]
    exported = False

    for label in export_candidates:
        try:
            link = page.get_by_role("link", name=label)
            if await link.count() > 0:
                await link.click()
                exported = True
                break
        except Exception:
            pass
        try:
            btn = page.get_by_role("button", name=label)
            if await btn.count() > 0:
                await btn.click()
                exported = True
                break
        except Exception:
            pass

    # Conservative fallback: click the first link or button whose accessible name contains 'csv' (case-insensitive)
    if not exported:
        try:
            links = page.get_by_role("link")
            if await links.count() > 0:
                total = await links.count()
                for i in range(total):
                    l = links.nth(i)
                    try:
                        name = (await l.get_attribute('innerText')) or ""
                    except Exception:
                        name = ""
                    if name and 'csv' in name.lower():
                        await l.click()
                        exported = True
                        break
        except Exception:
            pass

    if not exported:
        try:
            buttons = page.get_by_role("button")
            if await buttons.count() > 0:
                total = await buttons.count()
                for i in range(total):
                    b = buttons.nth(i)
                    try:
                        name = (await b.get_attribute('innerText')) or ""
                    except Exception:
                        name = ""
                    if name and 'csv' in name.lower():
                        await b.click()
                        exported = True
                        break
        except Exception:
            pass

    # Final: either export was attempted (last action) or the report was generated in-page.
    return

